// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/account/balance", wrapper.GetBalance)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/message/send", wrapper.SendMessage)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/message/{id}", wrapper.GetMessage)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/message/sendBulk", wrapper.SendBulk)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/message/list", wrapper.ListMessages)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/campaign/create", wrapper.CreateCampaign)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/campaign/{id}/summary", wrapper.CampaignSummary)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/alphaname/list", wrapper.ListAlphanames)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/otp/send", wrapper.SendOtp)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/otp/verify", wrapper.VerifyOtp)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/link/shorten", wrapper.ShortenLink)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/webhook", wrapper.ListWebhooks)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/webhook", wrapper.CreateWebhook)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/v1/webhook/{id}", wrapper.DeleteWebhook)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/webhook/{id}", wrapper.GetWebhook)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/v1/webhook/{id}", wrapper.UpdateWebhook)
	})

	return r
}

